1	    // The project-prompt request recorder (--project-prompt-requests).
2	    // Included inside class Scenario.
3	    //
4	    // tests/project_prompt asks a live model for one step at a known point of
5	    // a project chat. This plays each of its scripted conversations through
6	    // the real app up to that point -- the person's words, a canvas issue
7	    // button, a file opened -- with the model's outputs taken from the script
8	    // and every tool run for real, and keeps each request the script marks.
9	    // Only the script's words and calls are written by hand: the tool results,
10	    // the workspace context, the history and its replay rules are the app's.
11	    // The page's prompt and the tool list are checked against the files the
12	    // suite sends and left out of the output.
13	    //
14	    // At each kept request the script's "answers" reads are then called in
15	    // the same turn, and their results kept as the app returned them: the
16	    // suite answers a model's read with them. That ends the conversation, so
17	    // each kept request has a pass of its own, replaying the conversation
18	    // from the start, and no answer reaches another case's history.
19	
20	    // A person's edit of one or more print settings, through the print tab.
21	    void prompt_hand_edit(const nlohmann::json& changes)
22	    {
23	        DynamicPrintConfig diff;
24	        for (const auto& [key, value] : changes.items())
25	            diff.set_deserialize_strict(key, value.get<std::string>());
26	        wxGetApp().get_tab(Preset::TYPE_PRINT)->load_config(diff);
27	        wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, std::chrono::seconds(5));
28	    }
29	
30	    // The print settings and filament the first conversation started with.
31	    std::optional<DynamicPrintConfig> m_prompt_print;
32	    std::string                       m_prompt_filament;
33	
34	    // A new project keeps the edited print settings and the selected
35	    // filament, so an earlier conversation's changes are typed back and its
36	    // filament selected again.
37	    void prompt_restore_settings(const std::string& name)
38	    {
39	        PresetBundle& bundle = *wxGetApp().preset_bundle;
40	        if (!m_prompt_print) {
41	            m_prompt_print    = bundle.prints.get_edited_preset().config;
42	            m_prompt_filament = bundle.filaments.get_edited_preset().name;
43	            return;
44	        }
45	        const t_config_option_keys changed = bundle.prints.get_edited_preset().config.diff(*m_prompt_print);
46	        if (!changed.empty()) {
47	            DynamicPrintConfig back;
48	            back.apply_only(*m_prompt_print, changed);
49	            wxGetApp().get_tab(Preset::TYPE_PRINT)->load_config(back);
50	        }
51	        if (bundle.filaments.get_edited_preset().name != m_prompt_filament)
52	            SetupCommands::select_filament_preset(*m_plater, 0, m_prompt_filament);
53	        check(bundle.prints.get_edited_preset().config.diff(*m_prompt_print).empty() &&
54	                  bundle.filaments.get_edited_preset().name == m_prompt_filament,
55	              name + "_starts_from_the_first_settings");
56	    }
57	
58	    // The project each conversation starts from, with its current plate sliced.
59	    // `plate_type` (a curr_bed_type value, such as "Cool Plate") is the plate
60	    // the person selected in the sidebar before the slice. A new project
61	    // keeps the plate selected last (the prepare conversation's printer setup
62	    // selects the Textured PEI Plate), so every conversation names its own,
63	    // and a run of some conversations gets the plates a full run does.
64	    bool prompt_fixture(const std::string& kind, const std::string& name, const std::string& plate_type)
65	    {
66	        using namespace std::chrono_literals;
67	        // A slice the last conversation's model started may still be running.
68	        // When it ends the app starts a turn about it in that conversation;
69	        // that turn is answered with nothing, so this one starts clean.
70	        wait_for([this] { return !m_plater->is_background_process_slicing(); }, 120s);
71	        wait_for([] { return !g_held_model_requests.empty(); }, 2s);
72	        while (!g_held_model_requests.empty()) {
73	            HeldModelRequest request = std::move(g_held_model_requests.front());
74	            g_held_model_requests.pop_front();
75	            prompt_answer(request, nlohmann::json::array(), "");
76	            wait_for([this] { return !g_held_model_requests.empty() || !project_host().busy(); }, 10s);
77	        }
78	        prompt_restore_settings(name);
79	        if (kind == "overhang") {
80	            // print_issues_scenario's slab on one leg: slicing it warns.
81	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_new_project");
82	            const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
83	            const auto strategy = LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence;
84	            check(m_plater->load_files(std::vector<boost::filesystem::path>{cube}, strategy, false).size() == 1, name + "_cube_loaded");
85	            check(m_plater->load_files(std::vector<boost::filesystem::path>{write_overhang_stl()}, strategy, false).size() == 1,
86	                  name + "_overhang_loaded");
87	            PartPlateList& plates = m_plater->get_partplate_list();
88	            check(plates.get_plate(0)->add_instance(0, 0, true) == 0, name + "_cube_centred");
89	            check(plates.get_plate(0)->add_instance(1, 0, true) == 0, name + "_overhang_centred");
90	            m_plater->canvas3D()->reload_scene(true, true);
91	            move_object(1, Vec3d(70, 0, 0));
92	        } else if (kind == "single") {
93	            // One box on one plate, as a person who just added a model has.
94	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_new_project");
95	            const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
96	            const auto strategy = LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence;
97	            check(m_plater->load_files(std::vector<boost::filesystem::path>{cube}, strategy, false).size() == 1, name + "_cube_loaded");
98	            check(m_plater->get_partplate_list().get_plate(0)->add_instance(0, 0, true) == 0, name + "_cube_centred");
99	            m_plater->canvas3D()->reload_scene(true, true);
100	        } else {
101	            load_multi_plate_fixture();
102	        }
103	        check(!plate_type.empty(), name + "_names_its_plate");
104	        if (!plate_type.empty()) {
105	            // Selected only when it differs: selecting the plate already
106	            // selected still marks every plate on it unsliced.
107	            ConfigOptionEnum<BedType> plate;
108	            const bool known = plate.deserialize(plate_type);
109	            check(known, name + "_plate_type_known");
110	            if (known && wxGetApp().preset_bundle->project_config.opt_enum<BedType>("curr_bed_type") != plate.value)
111	                check(SetupCommands::select_bed_type(*m_plater, int(plate.value)), name + "_plate_selected");
112	        }
113	        const auto slice = [this](std::chrono::seconds limit) {
114	            wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, 10s);
115	            installed_shell()->status_row()->request_slice();
116	            return wait_for([this] {
117	                const auto* plate = m_plater->get_partplate_list().get_curr_plate();
118	                return plate && plate->is_slice_result_valid() && !m_plater->is_background_process_slicing();
119	            }, limit);
120	        };
121	        const bool sliced = slice(60s) || slice(120s);
122	        if (!sliced) {
123	            issue_monitor().refresh_now();
124	            for (const auto& issue : issues().issues)
125	                std::cerr << "HARNESS PROMPT " << name << " fixture issue " << issue.id << " '" << issue.message << "'\n";
126	        }
127	        check(sliced, name + "_fixture_sliced");
128	        installed_shell()->status_row()->request_prepare();
129	        wait_for([this] { return m_notebook->GetSelectedPageName() == TAB_ID_PREPARE && !m_plater->is_preview_shown(); }, 20s);
130	
131	        Agent::AgentHost& host = project_host();
132	        if (!host.conversation().empty())
133	            host.on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
134	                                                {"version", Agent::Protocol::kVersion},
135	                                                {"id", "prompt-new-" + name},
136	                                                {"type", Agent::Protocol::kCreateConversation},
137	                                                {"payload", nlohmann::json::object()}}
138	                                     .dump());
139	        const bool fresh = wait_for([&host] { return host.conversation().empty() && !host.busy(); }, 10s);
140	        check(fresh, name + "_starts_an_empty_chat");
141	        return sliced && fresh;
142	    }
143	
144	    // Where a step's model is copied under a name that says nothing about it.
145	    static std::string prompt_model_path(const std::string& name)
146	    {
147	        return (fs::path(data_dir()) / "prompt-models" / name).string();
148	    }
149	
150	    // Copies the source tree's `from` to prompt_model_path(`as`).
151	    bool prompt_copy_model(const nlohmann::json& copy, const std::string& name)
152	    {
153	        const fs::path target = prompt_model_path(copy.at("as").get<std::string>());
154	        boost::system::error_code error;
155	        fs::create_directories(target.parent_path(), error);
156	        fs::copy_file(fs::path(JUSPRIN_SOURCE_DIR) / copy.at("from").get<std::string>(), target,
157	                      fs::copy_options::overwrite_existing, error);
158	        check(!error, name + "_model_copied");
159	        return !error;
160	    }
161	
162	    // The page's skills the recorder checks for, as the page sends each one:
163	    // the SKILL.md body (skillParser.ts). Only the file-loaded skill brings
164	    // a picture of the plate.
165	    static constexpr const char* kPromptFileLoadedSkill = "file-loaded";
166	    static const std::vector<std::string>& prompt_skill_names()
167	    {
168	        static const std::vector<std::string> names{kPromptFileLoadedSkill, "print-issues", "project-setup-changed",
169	                                                     "slice-failed"};
170	        return names;
171	    }
172	    static std::string prompt_skill_text(const std::string& name)
173	    {
174	        std::ifstream file((fs::path(JUSPRIN_SOURCE_DIR) / "src/slic3r/GUI/JusPrin/AgentUI/src/skills" / name / "SKILL.md").string(),
175	                           std::ios::binary);
176	        std::string text((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
177	        // A Windows checkout has CRLF; the page sends the skill with LF.
178	        text.erase(std::remove(text.begin(), text.end(), '\r'), text.end());
179	        const std::size_t body = text.find("\n---\n");
180	        text = body == std::string::npos ? std::string() : text.substr(body + 5);
181	        text.erase(0, text.find_first_not_of('\n'));
182	        text.erase(text.find_last_not_of(" \n") + 1);
183	        return text;
184	    }
185	
186	    // Which skill an input item is (a developer item that starts with its
187	    // text), or empty; and whether it is a plate picture (a user item
188	    // holding one image and nothing else).
189	    static std::string prompt_skill_of(const nlohmann::json& item)
190	    {
191	        if (item.value("role", "") != "developer" || !item.contains("content") || !item["content"].is_string())
192	            return {};
193	        for (const std::string& name : prompt_skill_names()) {
194	            const std::string text = prompt_skill_text(name);
195	            if (!text.empty() && item["content"].get<std::string>().rfind(text, 0) == 0)
196	                return name;
197	        }
198	        return {};
199	    }
200	    static bool prompt_is_picture(const nlohmann::json& item)
201	    {
202	        return item.value("role", "") == "user" && item.contains("content") && item["content"].is_array() &&
203	               item["content"].size() == 1 && item["content"][0].value("type", "") == "input_image";
204	    }
205	    // The skills and the number of pictures among a request's last
206	    // `appended` items. A chat's requests repeat its record and append to it
207	    // (ba08e2c18f), and on the Responses API a fired skill stays in that
208	    // record: nothing hides it after its own request (fe70eea593). So a
209	    // skill "sent once" is one appended once, on the request that fired it,
210	    // and replayed unchanged as history after that.
211	    static std::pair<std::vector<std::string>, std::size_t> prompt_appended_skills(const nlohmann::json& input,
212	                                                                                   std::size_t appended)
213	    {
214	        std::pair<std::vector<std::string>, std::size_t> found;
215	        for (std::size_t i = input.size() - appended; i < input.size(); ++i) {
216	            if (const std::string skill = prompt_skill_of(input[i]); !skill.empty())
217	                found.first.push_back(skill);
218	            found.second += prompt_is_picture(input[i]) ? 1 : 0;
219	        }
220	        return found;
221	    }
222	
223	    // "{{file/<name>}}" is the path of a model a step copied under that name;
224	    // "{{attachment}}" the id of the file the person last attached;
225	    // "{{result/<pointer>}}" is the last tool result in this request;
226	    // "{{workspace/sessionId}}", "{{workspace/revision}}", "{{workspace/plateId/N}}" (the Nth plate),
227	    // "{{workspace/activePlateId}}", "{{workspace/firstObjectId}}" (the
228	    // active plate's first object), "{{workspace/filamentPreset}}" and
229	    // "{{workspace/printerPreset}}" the project now; "{{object}}" the object
230	    // an "eachObject" answer is being read for, "{{plate}}" the plate an
231	    // "eachPlate" answer is being read for.
232	    nlohmann::json prompt_fill(const nlohmann::json& value, const nlohmann::json& body, const std::string& name)
233	    {
234	        using nlohmann::json;
235	        if (value.is_object() || value.is_array()) {
236	            json filled = value;
237	            for (auto& [key, item] : filled.items())
238	                item = prompt_fill(item, body, name);
239	            return filled;
240	        }
241	        if (!value.is_string())
242	            return value;
243	        const std::string text = value;
244	        if (text.size() < 5 || text.rfind("{{", 0) != 0 || text.compare(text.size() - 2, 2, "}}") != 0)
245	            return value;
246	        const std::string path = text.substr(2, text.size() - 4);
247	        if (path == "object" && !m_prompt_object.empty())
248	            return m_prompt_object;
249	        if (path == "plate" && !m_prompt_plate.empty())
250	            return m_prompt_plate;
251	        if (path.rfind("file/", 0) == 0)
252	            return prompt_model_path(path.substr(5));
253	        if (path == "attachment" && !m_prompt_attachment.empty())
254	            return m_prompt_attachment;
255	        if (path == "workspace/sessionId")
256	            return std::to_string(installed_shell()->workspace()->snapshot().session.value());
257	        if (path == "workspace/revision")
258	            return installed_shell()->workspace()->snapshot().revision;
259	        if (path == "workspace/filamentPreset")
260	            return installed_shell()->workspace()->snapshot().setup.filament_preset;
261	        if (path == "workspace/printerPreset")
262	            return installed_shell()->workspace()->snapshot().setup.printer_preset;
263	        if (path.rfind("workspace/plateId/", 0) == 0) {
264	            const auto plates = installed_shell()->workspace()->snapshot().plates;
265	            const std::size_t number = std::stoul(path.substr(18));
266	            if (number >= 1 && number <= plates.size())
267	                return std::to_string(plates[number - 1].id.value());
268	        }
269	        if (path == "workspace/activePlateId" || path == "workspace/firstObjectId")
270	            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
271	                if (plate.active && (path == "workspace/activePlateId" || !plate.objects.empty()))
272	                    return std::to_string(path == "workspace/activePlateId" ? plate.id.value() : plate.objects.front().id.value());
273	        if (path.rfind("result/", 0) == 0) {
274	            const json& input = body.at("input");
275	            for (auto item = input.rbegin(); item != input.rend(); ++item)
276	                if (item->value("type", "") == "function_call_output") {
277	                    const json output = json::parse(item->at("output").get<std::string>());
278	                    const json::json_pointer pointer(path.substr(6));
279	                    if (output.contains("result") && output["result"].contains(pointer))
280	                        return output["result"][pointer];
281	                    break;
282	                }
283	        }
284	        check(false, name + "_fills " + text);
285	        return value;
286	    }
287	
288	    // Answers a held request with model output, as the service streams it.
289	    static void prompt_answer(HeldModelRequest& request, const nlohmann::json& output, const std::string& text)
290	    {
291	        using Event = Agent::AgentHttpEvent;
292	        const auto frame = [](const nlohmann::json& event) { return "event: message\ndata: " + event.dump() + "\n\n"; };
293	        if (!text.empty())
294	            request.answer(Event{Event::Kind::Data, frame({{"type", "response.output_text.delta"}, {"delta", text}}), {}, 0});
295	        request.answer(Event{Event::Kind::Data,
296	                             frame({{"type", "response.completed"}, {"response", {{"output", output}}}}), {}, 0});
297	        request.answer(Event{Event::Kind::Complete, {}, {}, 200});
298	    }
299	
300	    // The next request of this turn the model is asked, past any chat title.
301	    std::optional<HeldModelRequest> prompt_next_request()
302	    {
303	        for (;;) {
304	            if (!wait_for([] { return !g_held_model_requests.empty(); }, std::chrono::seconds(120)))
305	                return std::nullopt;
306	            HeldModelRequest request = std::move(g_held_model_requests.front());
307	            g_held_model_requests.pop_front();
308	            if (request.body.contains("tools"))
309	                return request;
310	            prompt_answer(request, nlohmann::json::array({{{"type", "message"}, {"role", "assistant"},
311	                                                           {"content", nlohmann::json::array({{{"type", "output_text"},
312	                                                                                               {"text", "Fixture chat"}}})}}}),
313	                          "Fixture chat");
314	        }
315	    }
316	
317	    std::string m_prompt_object;      // for "{{object}}"
318	    std::string m_prompt_plate;       // for "{{plate}}"
319	    std::string m_prompt_attachment;  // for "{{attachment}}"
320	    // Each chat's last request input this pass, by prompt_cache_key: what
321	    // the chat's next request repeats and appends to.
322	    std::map<std::string, nlohmann::json> m_prompt_chat_input;
323	
324	    // The person attaches a copied model to the chat, as the composer's file
325	    // picker does; its id, once the app has stored it, or empty.
326	    std::string prompt_attach(const nlohmann::json& copy, const std::string& name)
327	    {
328	        if (!prompt_copy_model(copy, name))
329	            return {};
330	        std::ifstream file(prompt_model_path(copy.at("as").get<std::string>()), std::ios::binary);
331	        const std::string bytes((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
332	        static int next = 0;
333	        const std::string client_id = "prompt-attachment-" + std::to_string(++next);
334	        Agent::AgentHost& host = project_host();
335	        host.on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
336	                                            {"version", Agent::Protocol::kVersion},
337	                                            {"id", "prompt-attach-" + std::to_string(next)},
338	                                            {"type", Agent::Protocol::kAttachFile},
339	                                            {"payload", {{"clientAttachmentId", client_id},
340	                                                         {"name", copy.at("as").get<std::string>()},
341	                                                         {"source", "picker"},
342	                                                         {"dataBase64", wxBase64Encode(bytes.data(), bytes.size()).utf8_string()}}}}
343	                                 .dump());
344	        const auto record = persistence().document().find_attachment_by_client_id(client_id);
345	        check(record.has_value() && record->kind == "model", name + "_model_attached");
346	        return record ? record->id : std::string();
347	    }
348	
349	    // The answers' reads called after the kept request, in the same turn;
350	    // returns each with the result the app gave, as the model would read it.
351	    // A read marked "eachObject" is called once for every object on every
352	    // plate, and an "allSettings" entry with it once for every object; one
353	    // marked "eachPlate" once for every plate. A read whose result brings a
354	    // picture (view_render) keeps the result's text only.
355	    // An "allSettings" entry reads every setting of its scope:
356	    // the keys come from the app's own settings_search (an empty query lists
357	    // them all, page by page; those pages are not kept), then settings_get
358	    // reads them 32 at a time. With "keysOf" it reads, under its scope, the
359	    // keys of the scopes named, read before it, that are not its own: how
360	    // the app answers a name asked for under the wrong scope. The workspace block every result
361	    // carries is kept once, beside them, and left out of each result that
362	    // repeats it exactly.
363	    nlohmann::json prompt_answers(const std::string& name, HeldModelRequest request, const nlohmann::json& script_reads)
364	    {
365	        using nlohmann::json;
366	        json answers = json::array();
367	        int  calls   = 0;
368	        const json kept = request.body.at("input");
369	        // One read in the turn; the result as the app gave it, or nothing.
370	        const auto call = [&](const std::string& tool, const json& arguments) -> std::optional<std::string> {
371	            const std::string call_id = "call_" + name + "_answer_" + std::to_string(++calls);
372	            prompt_answer(request, json::array({{{"type", "function_call"}, {"call_id", call_id}, {"name", tool},
373	                                                 {"arguments", arguments.dump()}}}), "");
374	            std::optional<HeldModelRequest> next = prompt_next_request();
375	            check(next.has_value(), name + "_answer_" + tool + "_returned");
376	            if (!next)
377	                return std::nullopt;
378	            request = std::move(*next);
379	            if (calls == 1) {
380	                // The next request repeats the kept one whole, its skill and
381	                // picture included, and appends neither again (see
382	                // prompt_appended_skills).
383	                const json& input = request.body.at("input");
384	                const bool repeats = input.size() >= kept.size() && std::equal(kept.begin(), kept.end(), input.begin());
385	                check(repeats, name + "_repeats_all_on_the_next_request");
386	                const auto [skills, pictures] = prompt_appended_skills(input, repeats ? input.size() - kept.size() : input.size());
387	                check(skills.empty() && pictures == 0, name + "_skill_and_picture_not_appended_on_the_next_request");
388	            }
389	            // The call's own result: a picture the call returned comes after
390	            // it, as a message of its own, and is not kept.
391	            const json& sent = request.body.at("input");
392	            const auto result = std::find_if(sent.rbegin(), sent.rend(), [&call_id](const json& item) {
393	                return item.value("type", "") == "function_call_output" && item.value("call_id", "") == call_id;
394	            });
395	            check(result != sent.rend(), name + "_answer_" + tool + "_has_its_result");
396	            if (result == sent.rend())
397	                return std::nullopt;
398	            const std::string output = result->at("output");
399	            const json parsed = json::parse(output);
400	            // A slice report, or a read of the slicing section, made while
401	            // this point's own slice runs is answered "busy"
402	            // (refuse_slice_poll): that is the app's answer at this point, and
403	            // the one the model gets.
404	            const bool busy_slicing = (tool == "workspace_inspect" || tool == "slice_report") && parsed.value("state", "") == "failed" &&
405	                                      parsed.contains("error") && parsed.at("error").value("code", "") == "busy";
406	            const bool answered = parsed.value("state", "") == "succeeded" || busy_slicing;
407	            check(answered, name + "_answer_" + tool + "_succeeded");
408	            return answered ? std::optional<std::string>(output) : std::nullopt;
409	        };
410	        std::map<std::string, std::vector<std::string>> scope_keys;
411	        bool ok = true;
412	        for (const json& read : script_reads) {
413	            if (!ok)
414	                break;
415	            std::vector<std::string> objects{std::string()};
416	            if (read.value("eachObject", false)) {
417	                objects.clear();
418	                for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
419	                    for (const auto& object : plate.objects)
420	                        objects.push_back(std::to_string(object.id.value()));
421	            }
422	            if (read.value("eachPlate", false)) {
423	                for (const auto& plate : installed_shell()->workspace()->snapshot().plates) {
424	                    if (!ok)
425	                        break;
426	                    m_prompt_plate = std::to_string(plate.id.value());
427	                    const json arguments = prompt_fill(read.value("arguments", json::object()), request.body, name);
428	                    const std::optional<std::string> output = call(read.at("call"), arguments);
429	                    if ((ok = output.has_value()))
430	                        answers.push_back({{"tool", read.at("call")}, {"arguments", arguments}, {"output", *output}});
431	                }
432	                m_prompt_plate.clear();
433	                continue;
434	            }
435	            if (read.contains("allSettings")) {
436	                const std::string scope = read["allSettings"];
437	                for (const std::string& object : objects) {
438	                    if (!ok)
439	                        break;
440	                    m_prompt_object = object;
441	                    const json target = prompt_fill(read.value("target", json()), request.body, name);
442	                    std::vector<std::string> keys;
443	                    if (read.contains("keysOf")) {
444	                        const auto& own = scope_keys[scope];
445	                        for (const json& other : read["keysOf"])
446	                            for (const std::string& key : scope_keys[other.get<std::string>()])
447	                                if (std::find(own.begin(), own.end(), key) == own.end())
448	                                    keys.push_back(key);
449	                    } else if (scope_keys.count(scope)) {
450	                        keys = scope_keys[scope];  // every object of the scope has the same settings
451	                    } else {
452	                        std::string cursor;
453	                        do {
454	                            json search{{"scope", scope}, {"query", ""}, {"limit", 25}};
455	                            if (!target.is_null())
456	                                search["target"] = target;
457	                            if (!cursor.empty())
458	                                search["cursor"] = cursor;
459	                            const std::optional<std::string> page = call("settings_search", search);
460	                            if (!(ok = page.has_value()))
461	                                break;
462	                            const json result = json::parse(*page).at("result");
463	                            for (const json& item : result.at("items"))
464	                                keys.push_back(item.at("key"));
465	                            cursor = result.value("nextCursor", "");
466	                        } while (!cursor.empty());
467	                        scope_keys[scope] = keys;
468	                    }
469	                    for (std::size_t first = 0; ok && first < keys.size(); first += 32) {
470	                        json arguments{{"scope", scope},
471	                                       {"keys", std::vector<std::string>(keys.begin() + first, keys.begin() + std::min(keys.size(), first + 32))}};
472	                        if (!target.is_null())
473	                            arguments["target"] = target;
474	                        const std::optional<std::string> output = call("settings_get", arguments);
475	                        if ((ok = output.has_value()))
476	                            answers.push_back({{"tool", "settings_get"}, {"arguments", arguments}, {"output", *output}});
477	                    }
478	                    std::cerr << "HARNESS PROMPT " << name << " allSettings " << scope << (object.empty() ? "" : " " + object)
479	                              << (read.contains("keysOf") ? " (other scopes' keys)" : "") << " keys=" << keys.size() << '\n';
480	                }
481	                continue;
482	            }
483	            for (const std::string& object : objects) {
484	                m_prompt_object = object;
485	                const json arguments = prompt_fill(read.value("arguments", json::object()), request.body, name);
486	                const std::optional<std::string> output = call(read.at("call"), arguments);
487	                if (!(ok = output.has_value()))
488	                    break;
489	                answers.push_back({{"tool", read.at("call")}, {"arguments", arguments}, {"output", *output}});
490	            }
491	        }
492	        m_prompt_object.clear();
493	        prompt_answer(request, json::array(), "");
494	        wait_for([this] { return !g_held_model_requests.empty() || !project_host().busy(); }, std::chrono::seconds(10));
495	        json shared = json::object();
496	        for (json& answer : answers) {
497	            json output = json::parse(answer["output"].get<std::string>());
498	            const json block{{"workspace", output.value("workspace", json())}, {"workspaceRevision", output.value("workspaceRevision", json())}};
499	            if (shared.empty())
500	                shared = block;
501	            if (block != shared)
502	                continue;
503	            output.erase("workspace");
504	            output.erase("workspaceRevision");
505	            answer["output"] = output.dump();
506	            answer["sharedWorkspace"] = true;
507	        }
508	        return {{"reads", answers}, {"shared", shared}};
509	    }
510	
511	    // One step of a conversation: what the person does, then the model's
512	    // scripted outputs, one per request the app sends, until they run out.
513	    // The record point numbered `target` is kept, with its answers, and ends
514	    // the conversation (2); otherwise 1, or 0 on a failure.
515	    int prompt_step(const std::string& name, const nlohmann::json& step, nlohmann::json& recorded,
516	                    const nlohmann::json& tools, const std::string& instructions, const nlohmann::json& reads,
517	                    int& point, int target)
518	    {
519	        using nlohmann::json;
520	        using namespace std::chrono_literals;
521	        Agent::AgentHost& host = project_host();
522	        const json        scripted = step.value("replies", json::array());
523	        std::deque<json>  replies(scripted.begin(), scripted.end());
524	
525	        // A person answers seconds later, after OrcaSlicer has taken in the
526	        // last turn's changes: a filament switched by printer_setup leaves
527	        // the plate's slice current until Orca's scheduled update runs.
528	        wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, 5s);
529	        if (step.contains("copy"))
530	            prompt_copy_model(step["copy"], name);
531	        json attached = json::array();
532	        if (step.contains("attach")) {
533	            m_prompt_attachment = prompt_attach(step["attach"], name);
534	            if (!m_prompt_attachment.empty())
535	                attached.push_back(m_prompt_attachment);
536	        }
537	        if (step.contains("slice")) {
538	            // The person presses Slice (true) or Slice all ("all") in the
539	            // status row, and waits for whatever OrcaSlicer does with it.
540	            // Neither is enabled for a plate OrcaSlicer's check has refused;
541	            // Slice all slices plate by plate and is refused at such a plate.
542	            installed_shell()->status_row()->request_slice(step["slice"] == "all");
543	            wait_for([this] { return !m_plater->is_background_process_slicing(); }, 120s);
544	            const auto snapshot = installed_shell()->workspace()->snapshot();
545	            for (const auto& plate : snapshot.plates)
546	                std::cerr << "HARNESS PROMPT " << name << " pressed Slice: plate " << plate.id.value() << " sliced=" << plate.sliced << " failure='"
547	                              << (plate.slice_failure ? plate.slice_failure->message : std::string()) << "'\n";
548	        }
549	        if (step.contains("say")) {
550	            std::string said = step["say"];
551	            for (std::size_t at; (at = said.find("{{file/")) != std::string::npos;) {
552	                const std::size_t end = said.find("}}", at);
553	                said.replace(at, end + 2 - at, prompt_model_path(said.substr(at + 7, end - at - 7)));
554	            }
555	            static int next = 0;
556	            ++next;
557	            host.on_page_message(json{{"protocol", Agent::Protocol::kName},
558	                                      {"version", Agent::Protocol::kVersion},
559	                                      {"id", "prompt-" + std::to_string(next)},
560	                                      {"type", Agent::Protocol::kUserMessage},
561	                                      {"payload", {{"clientMessageId", "prompt-c-" + std::to_string(next)}, {"text", said},
562	                                                   {"attachmentIds", attached}}}}
563	                                     .dump());
564	        } else if (step.contains("issue")) {
565	            // A setting typed in by hand, the issue OrcaSlicer reports for
566	            // it, and a press of one of the issue's two buttons.
567	            prompt_hand_edit(step.at("set"));
568	            const std::string setting = step.at("set").begin().key();
569	            std::string       issue_id;
570	            wait_for([&] {
571	                issue_monitor().refresh_now();
572	                for (const auto& issue : issues().issues)
573	                    if (issues().checked && issue.source == PrintIssues::IssueSource::Validation && issue.setting == setting)
574	                        issue_id = issue.id;
575	                return !issue_id.empty();
576	            }, 30s);
577	            check(!issue_id.empty(), name + "_issue_reported");
578	            const std::string outcome = issue_id.empty() ? "" : installed_shell()->submit_issue(issue_id, step["issue"]).outcome;
579	            std::cerr << "HARNESS PROMPT " << name << " issue " << issue_id << " outcome=" << outcome << '\n';
580	            check(outcome == "started", name + "_issue_sent_to_the_chat");
581	        } else if (step.contains("drop")) {
582	            // A model with a name that says nothing about it, imported by the
583	            // person into an empty project.
584	            check(prompt_copy_model(json{{"from", step.at("model")}, {"as", step["drop"]}}, name), name + "_model_ready");
585	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_empty_project");
586	            m_plater->add_model(false, prompt_model_path(step["drop"]));
587	        } else if (step.contains("open")) {
588	            // A project someone saved with an author note in its description,
589	            // written by the app's own exporter, then opened.
590	            if (!m_plater->model().model_info)
591	                m_plater->model().model_info = std::make_shared<ModelInfo>();
592	            m_plater->model().model_info->description = step.value("description", "");
593	            const fs::path file = fs::path(data_dir()) / (step["open"].get<std::string>() + ".3mf");
594	            check(m_plater->export_3mf(file, SaveStrategy::SplitModel | SaveStrategy::ShareMesh | SaveStrategy::Silence) >= 0,
595	                  name + "_project_saved");
596	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_saved_project_closed");
597	            m_plater->load_project(from_u8(file.string()), "-");
598	        }
599	
600	        bool expect_failure = false;
601	        int  calls          = 0;
602	        for (;;) {
603	            // The chat title is asked for after a reply ends; no case reads it.
604	            wait_for([&] { return !g_held_model_requests.empty() || (replies.empty() && !host.busy()); }, 120s);
605	            if (g_held_model_requests.empty()) {
606	                if (!replies.empty()) {
607	                    const auto snapshot = installed_shell()->workspace()->snapshot();
608	                    std::cerr << "HARNESS PROMPT " << name << " waiting: slicing.running=" << snapshot.slicing.running
609	                              << " orca_slicing=" << m_plater->is_background_process_slicing();
610	                    for (const auto& plate : snapshot.plates)
611	                        std::cerr << " plate " << plate.id.value() << " active=" << plate.active << " sliced=" << plate.sliced;
612	                    issue_monitor().refresh_now();
613	                    for (const auto& issue : issues().issues)
614	                        std::cerr << " | issue " << issue.id << " '" << issue.message << "'";
615	                    for (const auto& activity : host.tools().activities())
616	                        std::cerr << " | " << activity.tool << '=' << Agent::tool_state_name(activity.state);
617	                    std::cerr << '\n';
618	                }
619	                break;
620	            }
621	            HeldModelRequest request = std::move(g_held_model_requests.front());
622	            g_held_model_requests.pop_front();
623	            if (!request.body.contains("tools")) {
624	                prompt_answer(request, json::array({{{"type", "message"}, {"role", "assistant"},
625	                                                     {"content", json::array({{{"type", "output_text"}, {"text", "Fixture chat"}}})}}}),
626	                              "Fixture chat");
627	                continue;
628	            }
629	            const json& input = request.body.at("input");
630	            // What this request appends to the chat's last one.
631	            json&             last     = m_prompt_chat_input[request.body.value("prompt_cache_key", "")];
632	            const bool        appends  = last.is_null() || (input.size() >= last.size() && std::equal(last.begin(), last.end(), input.begin()));
633	            const std::size_t appended = appends ? input.size() - (last.is_null() ? 0 : last.size()) : input.size();
634	            last                       = input;
635	            if (!input.empty() && input.back().value("type", "") == "function_call_output") {
636	                const json output = json::parse(input.back().at("output").get<std::string>());
637	                const std::string state = output.value("state", "");
638	                std::cerr << "HARNESS PROMPT " << name << " result state=" << state
639	                          << (output.contains("error") ? " error=" + output["error"].value("code", "") : std::string()) << '\n';
640	                check((state == "failed") == expect_failure && state != "running", name + "_call_" + std::to_string(calls) + "_outcome");
641	            }
642	            if (replies.empty()) {
643	                check(false, name + "_unscripted_request");
644	                prompt_answer(request, json::array(), "");
645	                continue;
646	            }
647	            const json reply = replies.front();
648	            replies.pop_front();
649	            if (reply.contains("set"))
650	                prompt_hand_edit(reply["set"]);
651	            if (reply.contains("record") && point++ == target) {
652	                // The suite sends its own copies; they must be what the app sends.
653	                const std::string case_name = reply["record"];
654	                // Every request of the project chat offers the same tools,
655	                // whatever its message attaches, then the provider's own
656	                // search, which the suite adds itself (web_search()).
657	                json offered = tools;
658	                offered.push_back(json{{"type", "web_search"}});
659	                check(request.body.at("tools") == offered, case_name + "_tools_match_project_tools_json");
660	                check(request.body.at("instructions") == instructions, case_name + "_instructions_are_the_page_prompt");
661	                json kept = request.body;
662	                kept.erase("tools");
663	                kept.erase("instructions");
664	                // Names this run's project and chat, which the suite's own
665	                // requests are not.
666	                kept.erase("prompt_cache_key");
667	                const std::size_t items = input.size();
668	                // A point marked "skill" is the request where the model first
669	                // reads about that skill's event: it appends that skill, and
670	                // the plate's picture for the file-loaded skill. No other
671	                // point appends a skill or a picture, though it may replay
672	                // one an earlier request appended (prompt_appended_skills),
673	                // and an import's point appends the file-loaded skill alone.
674	                const std::string wanted   = reply.value("skill", "");
675	                const bool        pictured = wanted == kPromptFileLoadedSkill;
676	                check(appends, case_name + "_appends_to_the_chats_last_request");
677	                const auto [skills, pictures] = prompt_appended_skills(input, appended);
678	                check(skills == (wanted.empty() ? std::vector<std::string>{} : std::vector<std::string>{wanted}) &&
679	                          pictures == (pictured ? 1u : 0u),
680	                      case_name + (wanted.empty() ? "_appends_no_skill" : "_appends_" + wanted));
681	                const json recorded_reads = prompt_answers(case_name, std::move(request), reads);
682	                const json& answers = recorded_reads["reads"];
683	                recorded[case_name] = {{"body", kept}, {"answers", answers}, {"sharedWorkspace", recorded_reads["shared"]},
684	                                       {"appended", appended}};
685	                std::cerr << "HARNESS PROMPT recorded " << case_name << " input_items=" << items
686	                          << " bytes=" << kept.dump().size() << " answers=" << answers.size()
687	                          << " answer_bytes=" << answers.dump().size() << '\n';
688	                return 2;
689	            }
690	            json output = json::array();
691	            std::string text;
692	            if (reply.contains("text")) {
693	                text = reply["text"];
694	                output.push_back({{"type", "message"}, {"role", "assistant"},
695	                                  {"content", json::array({{{"type", "output_text"}, {"text", text}}})}});
696	            }
697	            if (reply.contains("call")) {
698	                ++calls;
699	                // The form the app replays a call in; a live model's own item
700	                // id and status are not reproducible.
701	                output.push_back({{"type", "function_call"},
702	                                  {"call_id", "call_" + name + "_" + std::to_string(calls)},
703	                                  {"name", reply["call"]},
704	                                  {"arguments", prompt_fill(reply.value("arguments", json::object()), request.body, name).dump()}});
705	                expect_failure = reply.value("fails", false);
706	                std::cerr << "HARNESS PROMPT " << name << " call " << reply["call"].get<std::string>() << ' '
707	                          << output.back()["arguments"].get<std::string>() << '\n';
708	            }
709	            prompt_answer(request, output, text);
710	        }
711	        check(replies.empty(), name + "_every_scripted_output_used");
712	        return replies.empty() ? 1 : 0;
713	    }
714	
715	    void record_prompt_requests()
716	    {
717	        using nlohmann::json;
718	        m_state->deadline = std::chrono::steady_clock::now() + std::chrono::minutes(30);
719	        const auto read = [](const fs::path& path) {
720	            std::ifstream file(path.string(), std::ios::binary);
721	            return std::string((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
722	        };
723	        const json script = json::parse(read(m_state->prompt_script), nullptr, false);
724	        const json tools  = json::parse(read(fs::path(JUSPRIN_SOURCE_DIR) / "tests/project_prompt/project_tools.json"), nullptr, false);
725	        std::string instructions =
726	            read(fs::path(JUSPRIN_SOURCE_DIR) / "src/slic3r/GUI/JusPrin/AgentUI/src/projectInstructions.fixture.txt");
727	        // A Windows checkout has CRLF; the page sends the prompt with LF.
728	        instructions.erase(std::remove(instructions.begin(), instructions.end(), '\r'), instructions.end());
729	        check(script.is_object() && script.contains("conversations"), "prompt_script_read");
730	        check(tools.is_array() && !instructions.empty(), "prompt_tools_and_instructions_read");
731	        for (const std::string& skill : prompt_skill_names())
732	            check(!prompt_skill_text(skill).empty(), "prompt_skill_text_read_" + skill);
733	        json recorded = json::object();
734	        const json reads = script.is_object() ? script.value("answers", json::array()) : json::array();
735	        bool ok = script.is_object() && tools.is_array();
736	        if (ok)
737	            for (const json& conversation : script["conversations"]) {
738	                const std::string name = conversation.at("name");
739	                int points = 0;
740	                for (const json& step : conversation.at("steps"))
741	                    for (const json& reply : step.value("replies", json::array()))
742	                        points += reply.contains("record") ? 1 : 0;
743	                // One pass per kept request: its answers end the conversation.
744	                for (int target = 0; ok && target < points; ++target) {
745	                    std::cerr << "HARNESS PROMPT conversation " << name << " point " << target << '\n';
746	                    if (!(ok = prompt_fixture(conversation.value("fixture", "plates"), name, conversation.value("plateType", ""))))
747	                        break;
748	                    m_prompt_chat_input.clear();
749	                    int point = 0, result = 1;
750	                    for (const json& step : conversation.at("steps"))
751	                        if (result == 1)
752	                            result = prompt_step(name, step, recorded, tools, instructions, reads, point, target);
753	                    check(result == 2, name + "_point_" + std::to_string(target) + "_kept");
754	                    ok = result == 2;
755	                }
756	                if (!ok)
757	                    break;
758	            }
759	        // The setting items of settings_get and settings_search results repeat
760	        // across reads and points: each distinct one is kept once, in
761	        // settingItems, and a result holds its index there instead.
762	        json items = json::array();
763	        std::map<std::string, std::size_t> index;
764	        for (auto& [case_name, kept] : recorded.items())
765	            for (json& answer : kept["answers"]) {
766	                if (answer["tool"] != "settings_get" && answer["tool"] != "settings_search")
767	                    continue;
768	                json output = json::parse(answer["output"].get<std::string>());
769	                for (const char* field : {"items", "unknownKeys"}) {
770	                    if (!output["result"].contains(field))
771	                        continue;
772	                    for (json& item : output["result"][field]) {
773	                        const auto [found, added] = index.emplace(item.dump(), items.size());
774	                        if (added)
775	                            items.push_back(item);
776	                        item = found->second;
777	                    }
778	                }
779	                answer["output"]       = output.dump();
780	                answer["settingItems"] = true;
781	            }
782	        std::ofstream output(m_state->prompt_requests.string(), std::ios::binary);
783	        output << json{{"settingItems", items}, {"cases", recorded}}.dump(1) << '\n';
784	        check(output.good(), "prompt_requests_written");
785	        finish();
786	    }
